// flashcard drill — JAH Bahamas Complete Profile Database (jahdb demo program)
var ITEMS=[["Bahamas: complete overview","Bahamas: parliamentary constitutional monarchy nation in Caribbean; capital Nassau; about about 410,000 people."], ["country","Bahamas"], ["capital","Nassau"], ["region","Caribbean"], ["population","about 410,000"]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
console.log("== drill ==");console.log(ask(5));

